// also unported.
/// Raven `G_SiegeSetObjectiveComplete`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:375-427`
pub fn G_SiegeSetObjectiveComplete(
    ctx: GameContext<'_>,
    team: c_int,
    objective: c_int,
    failIt: qboolean,
) {
    unsafe {
        // PORT-NOTE(missing-field): `gObjectiveCfgStr` referenced as
        // `(*ctx.world).globals.gObjectiveCfgStr` (missing_symbols — not yet a
        // GameWorld field). `strstr` has no ported home; inlined as a plain
        // byte scan (not a named helper) per the zero-park policy.
        let buf = (*ctx.world).globals.gObjectiveCfgStr.as_mut_ptr();
        let buf_len = core::ffi::CStr::from_ptr(buf).to_bytes().len();
        let needle: &[u8] = if team == SIEGETEAM_TEAM1 {
            b"t1"
        } else if team == SIEGETEAM_TEAM2 {
            b"t2"
        } else {
            b""
        };

        let mut p: *mut c_char = core::ptr::null_mut();
        if !needle.is_empty() {
            let mut i = 0usize;
            while i + needle.len() <= buf_len {
                if core::slice::from_raw_parts(buf.add(i) as *const u8, needle.len()) == needle {
                    p = buf.add(i);
                    break;
                }
                i += 1;
            }
        }

        if p.is_null() {
            // Raven: assert(0); return;
            return;
        }

        let mut onObjective: c_int = 0;

        // Parse from the beginning of this team's objectives until we get to
        // the desired objective number.
        while !p.is_null() && *p != 0 && *p != b'|' as c_char {
            if *p == b'-' as c_char {
                onObjective += 1;
            }

            if onObjective == objective {
                // this is the one we want; move to the status char.
                p = p.add(1);

                if failIt != 0 {
                    *p = b'0' as c_char;
                } else {
                    *p = b'1' as c_char;
                }
                break;
            }

            p = p.add(1);
        }

        // Now re-update the configstring.
        trap::SetConfigstring(
            ctx.engine,
            mp_abi::game::syscalls::G_SET_CONFIGSTRING::GSetConfigstringArgs::new(
                CS_SIEGE_OBJECTIVES,
                cstr(
                    &core::ffi::CStr::from_ptr((*ctx.world).globals.gObjectiveCfgStr.as_ptr())
                        .to_string_lossy(),
                ),
            ),
        );
    }
}

// PORT-NOTE(bg-boundary): reads `gObjectiveCfgStr`, a bg-tier siege
// global not yet a GameWorld field.
/// Raven `G_SiegeGetCompletionStatus` — qtrue if objective is currently complete.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:430-480`
pub fn G_SiegeGetCompletionStatus(ctx: GameContext<'_>, team: c_int, objective: c_int) -> qboolean {
    unsafe {
        // PORT-NOTE(missing-field): `gObjectiveCfgStr` referenced as
        // `(*ctx.world).globals.gObjectiveCfgStr` (missing_symbols). `strstr`
        // inlined as a plain byte scan per the zero-park policy (see
        // `G_SiegeSetObjectiveComplete`).
        let buf = (*ctx.world).globals.gObjectiveCfgStr.as_mut_ptr();
        let buf_len = core::ffi::CStr::from_ptr(buf).to_bytes().len();
        let needle: &[u8] = if team == SIEGETEAM_TEAM1 {
            b"t1"
        } else if team == SIEGETEAM_TEAM2 {
            b"t2"
        } else {
            b""
        };

        let mut p: *mut c_char = core::ptr::null_mut();
        if !needle.is_empty() {
            let mut i = 0usize;
            while i + needle.len() <= buf_len {
                if core::slice::from_raw_parts(buf.add(i) as *const u8, needle.len()) == needle {
                    p = buf.add(i);
                    break;
                }
                i += 1;
            }
        }

        if p.is_null() {
            // Raven: assert(0); return qfalse;
            return qfalse;
        }

        let mut onObjective: c_int = 0;

        while !p.is_null() && *p != 0 && *p != b'|' as c_char {
            if *p == b'-' as c_char {
                onObjective += 1;
            }

            if onObjective == objective {
                p = p.add(1);

                // return qtrue if it's '1', qfalse if it's anything else
                if *p == b'1' as c_char {
                    return qtrue;
                } else {
                    return qfalse;
                }
            }

            p = p.add(1);
        }

        qfalse
    }
}

/// Raven `UseSiegeTarget` — use the player who triggered the object to fire the
/// objective's target.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:482-526`
pub fn UseSiegeTarget(
    ctx: GameContext<'_>,
    other: *mut gentity_t,
    en: *mut gentity_t,
    target: *mut c_char,
) {
    unsafe {
        // Raven: "looks like we don't have access to a player, so just use
        // the activating entity" — when `en` has no client, all three uses
        // below (self-use test, GlobalUse activator/owner, inuse guard) target
        // `other` instead.
        let ent: *mut gentity_t = if en.is_null() || (*en).client.is_null() {
            other
        } else {
            en
        };

        if en.is_null() {
            return;
        }
        if target.is_null() {
            return;
        }

        let targetname_ofs = core::mem::offset_of!(gentity_t, targetname) as c_int;

        let mut t: *mut gentity_t = core::ptr::null_mut();
        loop {
            t = G_Find(ctx, t, targetname_ofs, target as *const c_char);
            if t.is_null() {
                break;
            }
            if t == ent {
                // G_Printf("WARNING: Entity used itself.\n") — no format args.
                crate::g_main::G_Printf(
                    ctx,
                    b"WARNING: Entity used itself.\n\0".as_ptr() as *const c_char,
                );
            } else if !(*t).use_.is_none() {
                GlobalUse(ctx, t, ent, ent);
            }
            if (*ent).inuse == 0 {
                crate::g_main::G_Printf(
                    ctx,
                    b"entity was removed while using targets\n\0".as_ptr() as *const c_char,
                );
                return;
            }
        }
    }
}

