// PORT-NOTE(unported-const): `AddScore(…, SIEGE_POINTS_OBJECTIVECOMPLETED)`
// — the `SIEGE_POINTS_*` score-award consts are not ported anywhere in the
// crate graph and their values are not in the packet (only the const/enum
// backfill list, which does not include them); a placeholder value would
// silently diverge from the oracle's actual scoring.
/// Raven `BroadcastObjectiveCompletion`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:555-564`
pub fn BroadcastObjectiveCompletion(
    ctx: GameContext<'_>,
    team: c_int,
    objective: c_int,
    r#final: c_int,
    client: c_int,
) {
    unsafe {
        // PORT-NOTE(unported-const): `SIEGE_POINTS_OBJECTIVECOMPLETED` has no
        // ported home yet; referenced verbatim (missing_symbols).
        if client != ENTITYNUM_NONE
            && !(*ctx.world).g_entities[client as usize].client.is_null()
            && (*((*ctx.world).g_entities[client as usize].client as *mut gclient_t))
                .sess
                .sessionTeam
                == team
        {
            // guy who completed this objective gets points, providing he's on
            // the opposing team
            AddScore(
                ctx,
                &mut (*ctx.world).g_entities[client as usize] as *mut gentity_t,
                (*((*ctx.world).g_entities[client as usize].client as *mut gclient_t))
                    .ps
                    .origin,
                SIEGE_POINTS_OBJECTIVECOMPLETED,
            );
        }

        SiegeBroadcast_OBJECTIVECOMPLETE(ctx, team, client, objective);
        // G_Printf("Broadcast goal completion team %i objective %i final %i\n", team, objective, final);
    }
}

/// Raven `AddSiegeWinningTeamPoints`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:566-589`
pub fn AddSiegeWinningTeamPoints(ctx: GameContext<'_>, team: c_int, winner: c_int) {
    unsafe {
        // PORT-NOTE(unported-const): `SIEGE_POINTS_TEAMWONROUND`/
        // `SIEGE_POINTS_FINALOBJECTIVECOMPLETED` have no ported home yet;
        // referenced verbatim (missing_symbols).
        let mut i: c_int = 0;

        while i < (MAX_CLIENTS) as i32 {
            let ent = &mut (*ctx.world).g_entities[i as usize] as *mut gentity_t;

            if !(*ent).client.is_null()
                && (*((*ent).client as *mut gclient_t)).sess.sessionTeam == team
            {
                if i == winner {
                    AddScore(
                        ctx,
                        ent,
                        (*((*ent).client as *mut gclient_t)).ps.origin,
                        SIEGE_POINTS_TEAMWONROUND + SIEGE_POINTS_FINALOBJECTIVECOMPLETED,
                    );
                } else {
                    AddScore(
                        ctx,
                        ent,
                        (*((*ent).client as *mut gclient_t)).ps.origin,
                        SIEGE_POINTS_TEAMWONROUND,
                    );
                }
            }

            i += 1;
        }
    }
}

