// PORT-NOTE(unported-const): compares/writes `SIEGETEAM_TEAM1`/
// `SIEGETEAM_TEAM2` — neither is ported anywhere in the crate graph (not even
// as a raw value in a comment) and their values are not in the packet; a
// placeholder would silently diverge from the oracle's actual team-index
// scheme.
/// Raven `SiegeDoTeamAssign` — yeah, this is great...
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:597-630`
pub fn SiegeDoTeamAssign(ctx: GameContext<'_>) {
    unsafe {
        let mut i: c_int = 0;

        // yeah, this is great...
        while i < (MAX_CLIENTS) as i32 {
            let ent = &mut (*ctx.world).g_entities[i as usize] as *mut gentity_t;

            if (*ent).inuse != 0
                && !(*ent).client.is_null()
                && (*((*ent).client as *mut gclient_t)).pers.connected == CON_CONNECTED
            {
                // a connected client, switch his frickin teams around
                let cl = (*ent).client as *mut gclient_t;
                if (*cl).sess.siegeDesiredTeam == SIEGETEAM_TEAM1 {
                    (*cl).sess.siegeDesiredTeam = SIEGETEAM_TEAM2;
                } else if (*cl).sess.siegeDesiredTeam == SIEGETEAM_TEAM2 {
                    (*cl).sess.siegeDesiredTeam = SIEGETEAM_TEAM1;
                }

                if (*cl).sess.sessionTeam == SIEGETEAM_TEAM1 {
                    SetTeamQuick(ctx, ent, SIEGETEAM_TEAM2, qfalse);
                } else if (*cl).sess.sessionTeam == SIEGETEAM_TEAM2 {
                    SetTeamQuick(ctx, ent, SIEGETEAM_TEAM1, qfalse);
                }
            }
            i += 1;
        }
    }
}

/// Raven `SiegeTeamSwitch`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:632-652`
pub fn SiegeTeamSwitch(ctx: GameContext<'_>, winTeam: c_int, winTime: c_int) {
    unsafe {
        trap::SiegePersGet(
            ctx.engine,
            mp_abi::game::syscalls::G_SIEGEPERSGET::GSiegepersgetArgs::new(
                &mut (*ctx.world).globals.g_siegePersistant as *mut siegePers_t,
            ),
        );
        if (*ctx.world).globals.g_siegePersistant.beatingTime != 0 {
            // was already in "switched" mode, change back. announce the
            // winning team. either the first team won again, or the second
            // team beat the time set by the initial team. In any case the
            // winTeam here is the overall winning team.
            SiegeSetCompleteData(ctx, winTeam);
            SiegeClearSwitchData(ctx);
        } else {
            // go into "beat their time" mode
            (*ctx.world).globals.g_siegePersistant.beatingTime = qtrue;
            (*ctx.world).globals.g_siegePersistant.lastTeam = winTeam;
            (*ctx.world).globals.g_siegePersistant.lastTime = winTime;

            trap::SiegePersSet(
                ctx.engine,
                mp_abi::game::syscalls::G_SIEGEPERSSET::GSiegeperssetArgs::new(
                    &(*ctx.world).globals.g_siegePersistant as *const siegePers_t,
                ),
            );
        }
    }
}

// PORT-NOTE(bg-boundary): reads the bg-tier siege globals (`team1`/
// `team2`/`siege_info`/`gParseObjectives`), not yet GameWorld fields (fork
// 8a), and calls `trap_SetConfigstring(CS_SIEGE_STATE, …)` —
// `CS_SIEGE_STATE` is also unported.
/// Raven `SiegeRoundComplete`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:654-742`
pub fn SiegeRoundComplete(ctx: GameContext<'_>, winningteam: c_int, winningclient: c_int) {
    unsafe {
        // PORT-NOTE(missing-fields): `team1`/`team2`/`gParseObjectives`
        // (game globals) and `siege_info` (bg-tier) referenced as
        // `(*ctx.world).globals.*`/`(*ctx.world).bg_state.*` — none of these
        // fields exist yet (missing_symbols). `CS_SIEGE_STATE` unported
        // (missing_symbols).
        let nomatter: vec3_t = [0.0, 0.0, 0.0];
        let mut teamstr: [c_char; 1024] = [0; 1024];
        let mut originalWinningClient = winningclient;
        let mut winningclient = winningclient;

        if winningclient != ENTITYNUM_NONE
            && !(*ctx.world).g_entities[winningclient as usize]
                .client
                .is_null()
            && (*((*ctx.world).g_entities[winningclient as usize].client as *mut gclient_t))
                .sess
                .sessionTeam
                != winningteam
        {
            // this person just won the round for the other team..
            winningclient = ENTITYNUM_NONE;
        }

        SiegeBroadcast_ROUNDOVER(ctx, winningteam, winningclient);

        AddSiegeWinningTeamPoints(ctx, winningteam, winningclient);

        // Instead of exiting like this, fire off a target, and let it handle
        // things. Can be a script or whatever the designer wants.
        if winningteam == SIEGETEAM_TEAM1 {
            write_cstr_field(
                &mut teamstr,
                &core::ffi::CStr::from_ptr((*ctx.world).globals.team1.as_ptr()).to_string_lossy(),
            );
        } else {
            write_cstr_field(
                &mut teamstr,
                &core::ffi::CStr::from_ptr((*ctx.world).globals.team2.as_ptr()).to_string_lossy(),
            );
        }

        trap::SetConfigstring(
            ctx.engine,
            mp_abi::game::syscalls::G_SET_CONFIGSTRING::GSetConfigstringArgs::new(
                CS_SIEGE_STATE,
                cstr(&format!("3|{}", (*ctx.world).level.time)),
            ),
        ); // ended
        (*ctx.world).globals.gSiegeRoundBegun = qfalse;
        (*ctx.world).globals.gSiegeRoundEnded = qtrue;
        (*ctx.world).globals.gSiegeRoundWinningTeam = winningteam;

        if BG_SiegeGetValueGroup(
            (*ctx.world).bg_state.siege_info.as_mut_ptr() as *mut c_char,
            teamstr.as_mut_ptr(),
            (*ctx.world).globals.gParseObjectives.as_mut_ptr(),
        ) != 0
        {
            if BG_SiegeGetPairedValue(
                (*ctx.world).globals.gParseObjectives.as_mut_ptr(),
                b"roundover_target\0".as_ptr() as *mut c_char,
                teamstr.as_mut_ptr(),
            ) == 0
            {
                // didn't find the name of the thing to target upon win, just
                // logexit now then.
                LogExit(ctx, cstr("Objectives completed").as_ptr());
                return;
            }

            if originalWinningClient == ENTITYNUM_NONE {
                // oh well, just find something active and use it then.
                let mut i: c_int = 0;

                while i < (MAX_CLIENTS) as i32 {
                    let ent = &mut (*ctx.world).g_entities[i as usize] as *mut gentity_t;

                    if (*ent).inuse != 0 {
                        // sure, you'll do.
                        originalWinningClient = (*ent).s.number;
                        break;
                    }

                    i += 1;
                }
            }
            G_UseTargets2(
                ctx,
                &mut (*ctx.world).g_entities[originalWinningClient as usize] as *mut gentity_t,
                &mut (*ctx.world).g_entities[originalWinningClient as usize] as *mut gentity_t,
                teamstr.as_ptr(),
            );
        }

        if (*ctx.world).cvars.g_siegeTeamSwitch.integer != 0
            && ((*ctx.world).globals.imperial_time_limit != 0
                || (*ctx.world).globals.rebel_time_limit != 0)
        {
            // handle stupid team switching crap
            let mut time: c_int = 0;
            if (*ctx.world).globals.imperial_time_limit != 0 {
                time = (*ctx.world).globals.imperial_time_limit
                    - ((*ctx.world).globals.gImperialCountdown - (*ctx.world).level.time);
            } else if (*ctx.world).globals.rebel_time_limit != 0 {
                time = (*ctx.world).globals.rebel_time_limit
                    - ((*ctx.world).globals.gRebelCountdown - (*ctx.world).level.time);
            }

            if time < 1 {
                time = 1;
            }
            SiegeTeamSwitch(ctx, winningteam, time);
        } else {
            // assure it's clear for next round
            SiegeClearSwitchData(ctx);
        }
    }
}

// PORT-NOTE(bg-boundary): indexes `bgSiegeClasses`/`bgNumSiegeClasses`
// (bg-tier siege globals, not yet GameWorld fields — still parked in
// `bg_saga.rs`).
/// Raven `G_ValidateSiegeClassForTeam`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:744-784`
pub fn G_ValidateSiegeClassForTeam(ctx: GameContext<'_>, ent: *mut gentity_t, team: c_int) {
    unsafe {
        let mut newClassIndex: c_int = -1;
        let cl = (*ent).client as *mut gclient_t;
        if (*cl).siegeClass == -1 {
            // uh.. sure.
            return;
        }

        let scl = &mut (*ctx.world).bg_state.bgSiegeClasses[(*cl).siegeClass as usize]
            as *mut siegeClass_t;

        let stm = BG_SiegeFindThemeForTeam(team, &(*ctx.world).bg_state);
        if !stm.is_null() {
            let mut i = 0;

            while i < (*stm).numClasses {
                // go through the team and see its valid classes, can we find
                // one that matches our current player class?
                if !(*stm).classes[i as usize].is_null() {
                    if Q_stricmp(
                        (*scl).name.as_ptr(),
                        (*(*stm).classes[i as usize]).name.as_ptr(),
                    ) == 0
                    {
                        // the class we're using is already ok for this team.
                        return;
                    }
                    if (*(*stm).classes[i as usize]).playerClass == (*scl).playerClass
                        || newClassIndex == -1
                    {
                        newClassIndex = i;
                    }
                }
                i += 1;
            }

            if newClassIndex != -1 {
                // ok, let's find it in the global class array
                (*cl).siegeClass = BG_SiegeFindClassIndexByName(
                    (*(*stm).classes[newClassIndex as usize]).name.as_ptr(),
                    &(*ctx.world).bg_state,
                );
                write_cstr_field(
                    &mut (*cl).sess.siegeClass,
                    &core::ffi::CStr::from_ptr(
                        (*(*stm).classes[newClassIndex as usize]).name.as_ptr(),
                    )
                    .to_string_lossy(),
                );
            }
        }
    }
}

/// Raven `SetTeamQuick` — bypass most of the normal checks in SetTeam.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:787-834`
pub fn SetTeamQuick(ctx: GameContext<'_>, ent: *mut gentity_t, team: c_int, doBegin: qboolean) {
    unsafe {
        // Raven's `MAX_INFO_STRING` is not yet a ported const (see
        // `q_shared.rs`'s `Info_SetValueForKey` precedent); hardcoded 1024
        // matching that precedent.
        let mut userinfo: [c_char; 1024] = [0; 1024];

        trap::GetUserinfo(
            ctx.engine,
            mp_abi::game::syscalls::G_GET_USERINFO::GGetUserinfoArgs::new(
                (*ent).s.number,
                userinfo.as_mut_ptr(),
                userinfo.len() as c_int,
            ),
        );

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            G_ValidateSiegeClassForTeam(ctx, ent, team);
        }

        let cl = (*ent).client as *mut gclient_t;
        (*cl).sess.sessionTeam = team;

        if team == TEAM_SPECTATOR {
            (*cl).sess.spectatorState = spectatorState_t::SPECTATOR_FREE;
            Info_SetValueForKey(
                userinfo.as_mut_ptr(),
                b"team\0".as_ptr() as *const c_char,
                b"s\0".as_ptr() as *const c_char,
            );
        } else {
            (*cl).sess.spectatorState = spectatorState_t::SPECTATOR_NOT;
            if team == TEAM_RED {
                Info_SetValueForKey(
                    userinfo.as_mut_ptr(),
                    b"team\0".as_ptr() as *const c_char,
                    b"r\0".as_ptr() as *const c_char,
                );
            } else if team == TEAM_BLUE {
                Info_SetValueForKey(
                    userinfo.as_mut_ptr(),
                    b"team\0".as_ptr() as *const c_char,
                    b"b\0".as_ptr() as *const c_char,
                );
            } else {
                Info_SetValueForKey(
                    userinfo.as_mut_ptr(),
                    b"team\0".as_ptr() as *const c_char,
                    b"?\0".as_ptr() as *const c_char,
                );
            }
        }

        let info_cstring =
            std::ffi::CString::new(core::ffi::CStr::from_ptr(userinfo.as_ptr()).to_bytes())
                .unwrap();
        trap::SetUserinfo(
            ctx.engine,
            mp_abi::game::syscalls::G_SET_USERINFO::GSetUserinfoArgs::new(
                (*ent).s.number,
                info_cstring,
            ),
        );

        (*cl).sess.spectatorClient = 0;

        (*cl).pers.teamState.state = playerTeamStateState_t::TEAM_BEGIN;

        ClientUserinfoChanged(ctx, (*ent).s.number);

        if doBegin != 0 {
            ClientBegin(ctx, (*ent).s.number, qfalse);
        }
    }
}

/// Raven `SiegeRespawn` — respawn a siege player, honoring a pending team switch.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:836-851`
pub fn SiegeRespawn(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let client = (*ent).client as *mut gclient_t;

        if (*client).sess.sessionTeam != (*client).sess.siegeDesiredTeam {
            SetTeamQuick(ctx, ent, (*client).sess.siegeDesiredTeam, qtrue);
        } else {
            ClientSpawn(ctx, ent);
            // add a teleportation effect
            let tent = G_TempEntity(
                ctx,
                (*client).ps.origin,
                entity_event_t::EV_PLAYER_TELEPORT_IN as c_int,
            );
            (*tent).s.clientNum = (*ent).s.clientNum;
        }
    }
}

// PORT-NOTE(bg-boundary): reads the bg-tier `siege_info` global (not yet
// a GameWorld field) and calls `trap_SetConfigstring(CS_SIEGE_STATE,
// …)` — `CS_SIEGE_STATE` is also unported.
/// Raven `SiegeBeginRound` — entNum is just used as something to fire targets
/// from.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:853-903`
pub fn SiegeBeginRound(ctx: GameContext<'_>, entNum: c_int) {
    unsafe {
        // entNum is just used as something to fire targets from.
        let mut targname: [c_char; 1024] = [0; 1024];

        if (*ctx.world).globals.g_preroundState == 0 {
            // if players are not ingame on round start then respawn them now
            let mut i: c_int = 0;
            let mut spawnEnt: qboolean = qfalse;

            // respawn everyone now
            while i < (MAX_CLIENTS) as i32 {
                let ent = &mut (*ctx.world).g_entities[i as usize] as *mut gentity_t;

                if (*ent).inuse != 0 && !(*ent).client.is_null() {
                    let cl = (*ent).client as *mut gclient_t;
                    if (*cl).sess.sessionTeam != TEAM_SPECTATOR
                        && (*cl).ps.pm_flags & PMF_FOLLOW == 0
                    {
                        // not a spec, just respawn them
                        spawnEnt = qtrue;
                    } else if (*cl).sess.sessionTeam == TEAM_SPECTATOR
                        && ((*cl).sess.siegeDesiredTeam == TEAM_RED
                            || (*cl).sess.siegeDesiredTeam == TEAM_BLUE)
                    {
                        // spectator but has a desired team
                        spawnEnt = qtrue;
                    }
                }

                if spawnEnt != 0 {
                    SiegeRespawn(ctx, ent);
                    spawnEnt = qfalse;
                }
                i += 1;
            }
        }

        // Now check if there's something to fire off at the round start, if
        // so do it.
        if BG_SiegeGetPairedValue(
            (*ctx.world).bg_state.siege_info.as_mut_ptr() as *mut c_char,
            b"roundbegin_target\0".as_ptr() as *mut c_char,
            targname.as_mut_ptr(),
        ) != 0
        {
            if targname[0] != 0 {
                G_UseTargets2(
                    ctx,
                    &mut (*ctx.world).g_entities[entNum as usize] as *mut gentity_t,
                    &mut (*ctx.world).g_entities[entNum as usize] as *mut gentity_t,
                    targname.as_ptr(),
                );
            }
        }

        trap::SetConfigstring(
            ctx.engine,
            mp_abi::game::syscalls::G_SET_CONFIGSTRING::GSetConfigstringArgs::new(
                CS_SIEGE_STATE,
                cstr(&format!("0|{}", (*ctx.world).level.time)),
            ),
        ); // we're ready to g0g0g0
    }
}

// PORT-NOTE(unported-const): the `SIEGE_ROUND_BEGIN_TIME` timing const
// and `trap_SetConfigstring(CS_SIEGE_STATE, …)` — neither `CS_SIEGE_STATE` nor
// `SIEGE_ROUND_BEGIN_TIME` is ported anywhere in the crate graph and their
// values are not in the packet.
/// Raven `SiegeCheckTimers`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:905-1013`
pub fn SiegeCheckTimers(ctx: GameContext<'_>) {
    unsafe {
        // PORT-NOTE(unported-const): `SIEGE_ROUND_BEGIN_TIME`/`CS_SIEGE_STATE`
        // have no ported home yet; referenced verbatim (missing_symbols).
        let mut i: c_int = 0;
        let mut numTeam1: c_int = 0;
        let mut numTeam2: c_int = 0;

        if (*ctx.world).cvars.g_gametype.integer != GT_SIEGE {
            return;
        }

        if (*ctx.world).level.intermissiontime != 0 {
            return;
        }

        if (*ctx.world).globals.gSiegeRoundEnded != 0 {
            return;
        }

        if (*ctx.world).globals.gSiegeRoundBegun == 0 {
            // check if anyone is active on this team - if not, keep the timer
            // set up.
            i = 0;

            while i < (MAX_CLIENTS) as i32 {
                let ent = &mut (*ctx.world).g_entities[i as usize] as *mut gentity_t;

                if !(*ent).client.is_null()
                    && (*ent).inuse != 0
                    && (*((*ent).client as *mut gclient_t)).pers.connected == CON_CONNECTED
                    && (*((*ent).client as *mut gclient_t)).sess.siegeDesiredTeam == SIEGETEAM_TEAM1
                {
                    numTeam1 += 1;
                }
                i += 1;
            }

            i = 0;

            while i < (MAX_CLIENTS) as i32 {
                let ent = &mut (*ctx.world).g_entities[i as usize] as *mut gentity_t;

                if !(*ent).client.is_null()
                    && (*ent).inuse != 0
                    && (*((*ent).client as *mut gclient_t)).pers.connected == CON_CONNECTED
                    && (*((*ent).client as *mut gclient_t)).sess.siegeDesiredTeam == SIEGETEAM_TEAM2
                {
                    numTeam2 += 1;
                }
                i += 1;
            }

            if (*ctx.world).cvars.g_siegeTeamSwitch.integer != 0
                && (*ctx.world).globals.g_siegePersistant.beatingTime != 0
            {
                (*ctx.world).globals.gImperialCountdown =
                    (*ctx.world).level.time + (*ctx.world).globals.g_siegePersistant.lastTime;
                (*ctx.world).globals.gRebelCountdown =
                    (*ctx.world).level.time + (*ctx.world).globals.g_siegePersistant.lastTime;
            } else {
                (*ctx.world).globals.gImperialCountdown =
                    (*ctx.world).level.time + (*ctx.world).globals.imperial_time_limit;
                (*ctx.world).globals.gRebelCountdown =
                    (*ctx.world).level.time + (*ctx.world).globals.rebel_time_limit;
            }
        }

        if (*ctx.world).globals.imperial_time_limit != 0 {
            // team1
            if (*ctx.world).globals.gImperialCountdown < (*ctx.world).level.time {
                SiegeRoundComplete(ctx, SIEGETEAM_TEAM2, ENTITYNUM_NONE);
                (*ctx.world).globals.imperial_time_limit = 0;
                return;
            }
        }

        if (*ctx.world).globals.rebel_time_limit != 0 {
            // team2
            if (*ctx.world).globals.gRebelCountdown < (*ctx.world).level.time {
                SiegeRoundComplete(ctx, SIEGETEAM_TEAM1, ENTITYNUM_NONE);
                (*ctx.world).globals.rebel_time_limit = 0;
                return;
            }
        }

        if (*ctx.world).globals.gSiegeRoundBegun == 0 {
            if numTeam1 == 0 || numTeam2 == 0 {
                // don't have people on both teams yet.
                (*ctx.world).globals.gSiegeBeginTime =
                    (*ctx.world).level.time + SIEGE_ROUND_BEGIN_TIME;
                trap::SetConfigstring(
                    ctx.engine,
                    mp_abi::game::syscalls::G_SET_CONFIGSTRING::GSetConfigstringArgs::new(
                        CS_SIEGE_STATE,
                        cstr("1"),
                    ),
                ); // "waiting for players on both teams"
            } else if (*ctx.world).globals.gSiegeBeginTime < (*ctx.world).level.time {
                // mark the round as having begun
                (*ctx.world).globals.gSiegeRoundBegun = qtrue;
                SiegeBeginRound(ctx, i); // perform any round start tasks
            } else if (*ctx.world).globals.gSiegeBeginTime
                > ((*ctx.world).level.time + SIEGE_ROUND_BEGIN_TIME)
            {
                (*ctx.world).globals.gSiegeBeginTime =
                    (*ctx.world).level.time + SIEGE_ROUND_BEGIN_TIME;
            } else {
                trap::SetConfigstring(
                    ctx.engine,
                    mp_abi::game::syscalls::G_SET_CONFIGSTRING::GSetConfigstringArgs::new(
                        CS_SIEGE_STATE,
                        cstr(&format!(
                            "2|{}",
                            (*ctx.world).globals.gSiegeBeginTime - SIEGE_ROUND_BEGIN_TIME
                        )),
                    ),
                ); // getting ready to begin
            }
        }
    }
}

// PORT-NOTE(unported-const): compares `team == SIEGETEAM_TEAM1` — not
// ported anywhere in the crate graph and its value is not in the packet.
/// Raven `SiegeObjectiveCompleted`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1015-1058`
pub fn SiegeObjectiveCompleted(
    ctx: GameContext<'_>,
    team: c_int,
    objective: c_int,
    r#final: c_int,
    client: c_int,
) {
    unsafe {
        let goals_completed: c_int;
        let goals_required: c_int;

        if (*ctx.world).globals.gSiegeRoundEnded != 0 {
            return;
        }

        // Update the configstring status
        G_SiegeSetObjectiveComplete(ctx, team, objective, qfalse);

        if r#final != -1 {
            if team == SIEGETEAM_TEAM1 {
                (*ctx.world).globals.imperial_goals_completed += 1;
            } else {
                (*ctx.world).globals.rebel_goals_completed += 1;
            }
        }

        if team == SIEGETEAM_TEAM1 {
            goals_completed = (*ctx.world).globals.imperial_goals_completed;
            goals_required = (*ctx.world).globals.imperial_goals_required;
        } else {
            goals_completed = (*ctx.world).globals.rebel_goals_completed;
            goals_required = (*ctx.world).globals.rebel_goals_required;
        }

        if r#final == 1 || goals_completed >= goals_required {
            SiegeRoundComplete(ctx, team, client);
        } else {
            BroadcastObjectiveCompletion(ctx, team, objective, r#final, client);
        }
    }
}

// PORT-NOTE(bg-boundary): reads the bg-tier siege globals (`siege_valid`/
// `team1`/`team2`/`siege_info`/`gParseObjectives`), none of which are GameWorld
// fields yet (still parked in `bg_saga.rs`).
/// Raven `siegeTriggerUse`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1060-1128`
pub fn siegeTriggerUse(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        let mut teamstr: [c_char; 64] = [0; 64];
        let mut objectivestr: [c_char; 64] = [0; 64];
        let mut desiredobjective: [c_char; MAX_SIEGE_INFO_SIZE as usize] =
            [0; MAX_SIEGE_INFO_SIZE as usize];
        let mut clUser: c_int = ENTITYNUM_NONE;
        let mut r#final: c_int = 0;

        if (*ctx.world).bg_state.siege_valid == 0 {
            return;
        }

        if (*ent).s.eFlags & EF_RADAROBJECT == 0 {
            // toggle radar on and exit if it is not showing up already
            (*ent).s.eFlags |= EF_RADAROBJECT;
            return;
        }

        if !activator.is_null() && !(*activator).client.is_null() {
            // activator will hopefully be the person who triggered this event
            clUser = (*activator).s.number;
        }

        if (*ent).side == SIEGETEAM_TEAM1 {
            write_cstr_field(
                &mut teamstr,
                &core::ffi::CStr::from_ptr((*ctx.world).globals.team1.as_ptr()).to_string_lossy(),
            );
        } else {
            write_cstr_field(
                &mut teamstr,
                &core::ffi::CStr::from_ptr((*ctx.world).globals.team2.as_ptr()).to_string_lossy(),
            );
        }

        if BG_SiegeGetValueGroup(
            (*ctx.world).bg_state.siege_info.as_mut_ptr() as *mut c_char,
            teamstr.as_mut_ptr(),
            (*ctx.world).globals.gParseObjectives.as_mut_ptr(),
        ) != 0
        {
            write_cstr_field(&mut objectivestr, &format!("Objective{}", (*ent).objective));

            if BG_SiegeGetValueGroup(
                (*ctx.world).globals.gParseObjectives.as_mut_ptr(),
                objectivestr.as_mut_ptr(),
                desiredobjective.as_mut_ptr(),
            ) != 0
            {
                if BG_SiegeGetPairedValue(
                    desiredobjective.as_mut_ptr(),
                    b"final\0".as_ptr() as *mut c_char,
                    teamstr.as_mut_ptr(),
                ) != 0
                {
                    r#final = atoi(teamstr.as_ptr());
                }

                if BG_SiegeGetPairedValue(
                    desiredobjective.as_mut_ptr(),
                    b"target\0".as_ptr() as *mut c_char,
                    teamstr.as_mut_ptr(),
                ) != 0
                {
                    let mut i: isize = 0;
                    while teamstr[i as usize] != 0 {
                        if teamstr[i as usize] == b'\r' as c_char
                            || teamstr[i as usize] == b'\n' as c_char
                        {
                            teamstr[i as usize] = 0;
                        }
                        i += 1;
                    }
                    UseSiegeTarget(ctx, other, activator, teamstr.as_mut_ptr());
                }

                if !(*ent).target.is_null() && *(*ent).target != 0 {
                    // use this too
                    UseSiegeTarget(ctx, other, activator, (*ent).target);
                }

                SiegeObjectiveCompleted(ctx, (*ent).side, (*ent).objective, r#final, clUser);
            }
        }
    }
}

// PORT-NOTE(bg-boundary): reads the bg-tier `siege_valid` global (not
// yet a GameWorld field); also uses the unported
// `SIEGEITEM_STARTOFFRADAR` spawnflag const.
/// Raven `SP_info_siege_objective`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1137-1179`
pub fn SP_info_siege_objective(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let mut s: *mut c_char = core::ptr::null_mut();

        if (*ctx.world).bg_state.siege_valid == 0
            || (*ctx.world).cvars.g_gametype.integer != GT_SIEGE
        {
            crate::g_utils::G_FreeEntity(ctx, ent);
            return;
        }

        (*ent).use_ = Some(EntUse::siegeTriggerUse).into();
        G_SpawnInt(
            ctx,
            b"objective\0".as_ptr() as *const c_char,
            b"0\0".as_ptr() as *const c_char,
            &mut (*ent).objective,
        );
        G_SpawnInt(
            ctx,
            b"side\0".as_ptr() as *const c_char,
            b"0\0".as_ptr() as *const c_char,
            &mut (*ent).side,
        );

        if (*ent).objective == 0 || (*ent).side == 0 {
            // j00 fux0red something up
            crate::g_utils::G_FreeEntity(ctx, ent);
            crate::g_main::G_Printf(
                ctx,
                cstr("ERROR: info_siege_objective without an objective or side value\n").as_ptr(),
            );
            return;
        }

        // Set it up to be drawn on radar
        if (*ent).spawnflags & SIEGEITEM_STARTOFFRADAR == 0 {
            (*ent).s.eFlags |= EF_RADAROBJECT;
        }

        // All clients want to know where it is at all times for radar
        (*ent).r.svFlags |= SVF_BROADCAST;

        G_SpawnString(
            ctx,
            b"icon\0".as_ptr() as *const c_char,
            b"\0".as_ptr() as *const c_char,
            &mut s,
        );

        if !s.is_null() && *s != 0 {
            // We have an icon, so index it now. We are reusing the
            // genericenemyindex variable rather than adding a new one to the
            // entity state.
            (*ent).s.genericenemyindex = G_IconIndex(ctx, s as *const c_char);
        }

        (*ent).s.brokenLimbs = (*ent).side;
        (*ent).s.frame = (*ent).objective;
        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
        );
    }
}

// PORT-NOTE(unported-const): toggles `s.eFlags & EF_RADAROBJECT`; the
// `EF_RADAROBJECT` eflags bit is not ported anywhere in the crate graph and
// its value is not in the packet (same blocker as `g_turret_G2.rs`'s
// `SP_misc_turretG2` park — no committed value exists anywhere to reuse).
/// Raven `SiegeIconUse` — toggle it on and off.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1182-1194`
pub fn SiegeIconUse(ent: *mut gentity_t, other: *mut gentity_t, activator: *mut gentity_t) {
    // toggle it on and off
    unsafe {
        if (*ent).s.eFlags & EF_RADAROBJECT != 0 {
            (*ent).s.eFlags &= !EF_RADAROBJECT;
            (*ent).r.svFlags &= !SVF_BROADCAST;
        } else {
            (*ent).s.eFlags |= EF_RADAROBJECT;
            (*ent).r.svFlags |= SVF_BROADCAST;
        }
    }
}

// PORT-NOTE(bg-boundary): reads the bg-tier `siege_valid` global (not
// yet a GameWorld field); also calls `Com_Error` (variadic — the
// call site here passes no format args, so that part is not itself blocking)
// and uses the unported `EF_RADAROBJECT` eflags bit.
/// Raven `SP_info_siege_radaricon`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1203-1234`
pub fn SP_info_siege_radaricon(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let mut s: *mut c_char = core::ptr::null_mut();
        let mut i: c_int = 0;

        if (*ctx.world).bg_state.siege_valid == 0
            || (*ctx.world).cvars.g_gametype.integer != GT_SIEGE
        {
            crate::g_utils::G_FreeEntity(ctx, ent);
            return;
        }

        G_SpawnInt(
            ctx,
            b"startoff\0".as_ptr() as *const c_char,
            b"0\0".as_ptr() as *const c_char,
            &mut i,
        );

        if i == 0 {
            // start on then
            (*ent).s.eFlags |= EF_RADAROBJECT;
            (*ent).r.svFlags |= SVF_BROADCAST;
        }

        G_SpawnString(
            ctx,
            b"icon\0".as_ptr() as *const c_char,
            b"\0".as_ptr() as *const c_char,
            &mut s,
        );
        if s.is_null() || *s == 0 {
            // that's the whole point of the entity
            crate::g_main::Com_Error(
                (ERR_DROP) as i32,
                cstr("misc_siege_radaricon without an icon").as_ptr(),
            );
            return;
        }

        (*ent).use_ = Some(EntUse::SiegeIconUse).into();

        (*ent).s.genericenemyindex = G_IconIndex(ctx, s as *const c_char);

        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
        );
    }
}

// PORT-NOTE(bg-boundary): reads the bg-tier siege globals (`team1`/
// `team2`/`siege_info`/`gParseObjectives`), not yet GameWorld fields.
/// Raven `decompTriggerUse`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1236-1291`
pub fn decompTriggerUse(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        let mut r#final: c_int = 0;
        let mut teamstr: [c_char; 1024] = [0; 1024];
        let mut objectivestr: [c_char; 64] = [0; 64];
        let mut desiredobjective: [c_char; MAX_SIEGE_INFO_SIZE as usize] =
            [0; MAX_SIEGE_INFO_SIZE as usize];

        if (*ctx.world).globals.gSiegeRoundEnded != 0 {
            return;
        }

        if G_SiegeGetCompletionStatus(ctx, (*ent).side, (*ent).objective) == 0 {
            // if it's not complete then there's nothing to do here
            return;
        }

        // Update the configstring status
        G_SiegeSetObjectiveComplete(ctx, (*ent).side, (*ent).objective, qtrue);

        // Find out if this objective counts toward the final objective count
        if (*ent).side == SIEGETEAM_TEAM1 {
            write_cstr_field(
                &mut teamstr,
                &core::ffi::CStr::from_ptr((*ctx.world).globals.team1.as_ptr()).to_string_lossy(),
            );
        } else {
            write_cstr_field(
                &mut teamstr,
                &core::ffi::CStr::from_ptr((*ctx.world).globals.team2.as_ptr()).to_string_lossy(),
            );
        }

        if BG_SiegeGetValueGroup(
            (*ctx.world).bg_state.siege_info.as_mut_ptr() as *mut c_char,
            teamstr.as_mut_ptr(),
            (*ctx.world).globals.gParseObjectives.as_mut_ptr(),
        ) != 0
        {
            write_cstr_field(&mut objectivestr, &format!("Objective{}", (*ent).objective));

            if BG_SiegeGetValueGroup(
                (*ctx.world).globals.gParseObjectives.as_mut_ptr(),
                objectivestr.as_mut_ptr(),
                desiredobjective.as_mut_ptr(),
            ) != 0
            {
                if BG_SiegeGetPairedValue(
                    desiredobjective.as_mut_ptr(),
                    b"final\0".as_ptr() as *mut c_char,
                    teamstr.as_mut_ptr(),
                ) != 0
                {
                    r#final = atoi(teamstr.as_ptr());
                }
            }
        }

        // Subtract the goal num if applicable
        if r#final != -1 {
            if (*ent).side == SIEGETEAM_TEAM1 {
                (*ctx.world).globals.imperial_goals_completed -= 1;
            } else {
                (*ctx.world).globals.rebel_goals_completed -= 1;
            }
        }
    }
}

